nums = [1, 5, 233, 7]

@lru_cache(None)
def best_score(i, j):
    if i > j:
        return 0

    pick_left = nums[i] - best_score(i + 1, j)
    pick_right = nums[j] - best_score(i, j - 1)
    return max(pick_left, pick_right)

result = best_score(0, len(nums) - 1)
print(result)
print(result >= 0)
